exercise.solution:
fn contains(root: &str, candidate: &str) -> bool {
    fn norm(p: &str) -> Vec<String> {
        let mut parts: Vec<String> = Vec::new();
        for seg in p.split('/') {
            match seg {
                "" | "." => {}
                ".." => { parts.pop(); }
                other => parts.push(other.to_string()),
            }
        }
        parts
    }
    let r = norm(root);
    let c = norm(candidate);
    c.starts_with(&r)
}

fn main() {
    println!("{}", contains("/ws", "/ws/../ws/a"));
    println!("{}", contains("/ws", "/etc"));
}
